static struct ListNode* merge(struct ListNode*a,struct ListNode*b){struct ListNode d={0,0},*t=&d;while(a&&b){if(a->val<=b->val){t->next=a;a=a->next;}else{t->next=b;b=b->next;}t=t->next;}t->next=a?a:b;return d.next;}struct ListNode* mergeKLists(struct ListNode**lists,int n){if(!n)return 0;for(int step=1;step<n;step*=2)for(int i=0;i+step<n;i+=2*step)lists[i]=merge(lists[i],lists[i+step]);return lists[0];}
